def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    out = [row[:] for row in grid]
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != background:
            out[r] = [2] * w
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if len(set(vals)) == 1 and vals[0] != background:
            for r in range(h):
                out[r][c] = 2
    return out
